import {createStore} from "zustand/vanilla";
const store=createStore(()=>({count:0}));
const stop=store.subscribe(state=>console.log(state.count));
store.setState({count:1});
stop();
store.setState({count:2});

import {create} from "zustand";
import {persist} from "zustand/middleware";
export const useTheme=create(persist(set=>({theme:"light",choose:theme=>set({theme})}),{name:"club-theme",partialize:state=>({theme:state.theme})}));

